"use strict";

// === Upload Panel Toggle ===
var uploadPanel = document.getElementById('addon-upload-panel');
var installBtn = document.getElementById('addon-install-btn');
var fileInput = document.getElementById('addon-module');
var fileDisplay = document.getElementById('addon-file-display');
var normalView = document.getElementById('addons-normal-view');
var uploadBtnRow = installBtn ? installBtn.parentElement : null;

// Show/Hide upload form on button click
installBtn.addEventListener('click', function() {
    uploadPanel.style.display = 'block';
    if (normalView) normalView.style.display = 'none';
    if (uploadBtnRow) uploadBtnRow.style.display = 'none';
    uploadPanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
});

// Cancel button hides the form
document.getElementById('cancel-addform').addEventListener('click', function() {
    uploadPanel.style.display = 'none';
    if (normalView) normalView.style.display = 'block';
    if (uploadBtnRow) uploadBtnRow.style.display = 'flex'; // D-flex is used on the wrapper originally
});

// File input: show selected file name in the text field
if (fileInput && fileDisplay) {
    fileInput.addEventListener('change', function() {
        if (this.files && this.files.length > 0) {
            fileDisplay.value = this.files[0].name;
        } else {
            fileDisplay.value = '';
        }
    });
}

// === Alert Close ===
var alertCloseButtons = document.querySelectorAll('.addon-wb-alert-close');
alertCloseButtons.forEach(function(btn) {
    btn.addEventListener('click', function() {
        var alertEl = this.closest('.addon-wb-alert');
        alertEl.style.opacity = '0';
        setTimeout(function() {
            alertEl.style.display = 'none';
        }, 300);
    });
});

// === Settings Modal ===
var httpRequest;
var triggers = document.querySelectorAll('.addon-modal-trigger');

if (window.XMLHttpRequest) {
    httpRequest = new XMLHttpRequest();
} else if (window.ActiveXObject) {
    httpRequest = new ActiveXObject("Microsoft.XMLHTTP");
}

triggers.forEach(function(trigger) {
    trigger.addEventListener('click', function() {
        clearForm();
        addonModalToggle();
        setFormName(this.dataset.name);
        getAddonFormData(this.dataset.url);
    });
});

document.querySelector('.addon-modal-close').addEventListener('click', function() {
    addonModalToggle();
});

function getAddonFormData(url) {
    if (url === '#') return;
    toggleAddonLoading();
    httpRequest.onreadystatechange = handleResponse;
    httpRequest.open('GET', url, true);
    httpRequest.send();
}

function addonModalToggle() {
    document.querySelector('.addon-modal-window').classList.toggle('addon-modal-hidden');
}

function handleResponse() {
    if (httpRequest.readyState === XMLHttpRequest.DONE) {
        toggleAddonLoading();
        if (httpRequest.status === 200) {
            var response = JSON.parse(httpRequest.responseText);
            if (response.status) {
                generateForm(response.html);
            }
        } else {
            alert('There was a problem with the request.');
            addonModalToggle();
        }
    }
}

function generateForm(html) {
    var div = document.createElement("div");
    div.innerHTML = html;
    document.querySelector('.modal-form-data .form').appendChild(div);
}

function setFormName(name) {
    document.querySelector('.addon-modal-title').innerHTML = name;
}

function toggleAddonLoading() {
    document.querySelector('.addon-form-loading').classList.toggle('addon-modal-dnone');
}

function clearForm() {
    document.querySelector('.modal-form-data .form').innerHTML = '';
    setFormName('');
}

// === Tab Switching ===
var insTab = document.getElementById('ins-addon-tab');
var avlTab = document.getElementById('avl-addon-tab');
var insTable = document.getElementById('addons-ins-table-container');
var avlTable = document.getElementById('addons-avl-table-container');

$(document).ready(function() {
    $('.addon-wb-tab').on('click', function() {
        // Remove active from all tabs
        $('.addon-wb-tab').removeClass('addon-wb-tab-active');
        $(this).addClass('addon-wb-tab-active');

        if (this === insTab || this.id === 'ins-addon-tab') {
            insTable.style.display = '';
            insTable.classList.remove('addons-hide');
            avlTable.style.display = 'none';
            avlTable.classList.add('addons-hide');
        } else {
            avlTable.style.display = '';
            avlTable.classList.remove('addons-hide');
            insTable.style.display = 'none';
            insTable.classList.add('addons-hide');
        }
    });

    // === Search ===
    $('.search-box').on('keyup', function() {
        var filter = $(this).val().toUpperCase();
        var activeTable = insTable.classList.contains('addons-hide') ? avlTable : insTable;
        var rows = activeTable.querySelectorAll('tbody tr');

        for (var i = 0; i < rows.length; i++) {
            var nameEl = rows[i].querySelector('.addon-wb-name');
            if (nameEl) {
                var txtValue = nameEl.textContent || nameEl.innerText;
                rows[i].style.display = txtValue.toUpperCase().indexOf(filter) > -1 ? '' : 'none';
            }
        }
    });
});
